import{_ as o,a as n,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"第三册：培养技能 · 全册语法总结 · 感官动词后的补语至不定代词的后置修饰","description":"按课时归集语法规则、原创例句和易错边界。","frontmatter":{"title":"第三册：培养技能 · 全册语法总结 · 感官动词后的补语至不定代词的后置修饰","description":"按课时归集语法规则、原创例句和易错边界。","splitFrom":"life/english/new-concept/book-3/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 全册语法总结","summary":"按课时归集语法规则、原创例句和易错边界。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 全册语法总结 · 地点介词与移动路径至最高级的范围与倍数","link":"/life/english/new-concept/book-3/grammar-part-02"},"next":{"text":"第三册：培养技能 · 全册语法总结 · 条件句中的礼貌距离至by、until 与时刻表现在时","link":"/life/english/new-concept/book-3/grammar-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 全册语法总结 · 地点介词与移动路径至最高级的范围与倍数","link":"/life/english/new-concept/book-3/grammar-part-02"},"next":{"text":"第三册：培养技能 · 全册语法总结 · 条件句中的礼貌距离至by、until 与时刻表现在时","link":"/life/english/new-concept/book-3/grammar-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-3/grammar-part-03.md","filePath":"life/english/new-concept/book-3/grammar-part-03.md"}'),r={name:"life/english/new-concept/book-3/grammar-part-03.md"};function s(i,e,h,l,p,d){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="第三册-培养技能-·-全册语法总结-·-感官动词后的补语至不定代词的后置修饰" tabindex="-1">第三册：培养技能 · 全册语法总结 · 感官动词后的补语至不定代词的后置修饰 <a class="header-anchor" href="#第三册-培养技能-·-全册语法总结-·-感官动词后的补语至不定代词的后置修饰" aria-label="Permalink to &quot;第三册：培养技能 · 全册语法总结 · 感官动词后的补语至不定代词的后置修饰&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><h2 id="感官动词后的补语" tabindex="-1">感官动词后的补语 <a class="header-anchor" href="#感官动词后的补语" aria-label="Permalink to &quot;感官动词后的补语 {#感官动词后的补语}&quot;">​</a></h2><p>see、hear、watch、notice 等动词后可用宾语加动词原形，强调观察到完整动作或动作事实；也可用宾语加 ing，强调动作正在进行的片段。主动结构一般不用 to，如 saw the light flash。变为被动时，原形结构通常恢复 to，例如 was seen to leave；ing 结构仍保留 ing。实际语境可能让两种形式都成立，但表达视角不同。描述作品时，先报告感官证据，再给出解读，不能把自己的解释写成眼睛直接看到的事实。</p><p><strong>L18 原创例句：</strong> We watched the metal rings rotating while a low tone filled the room.</p><p>低沉的声音充满房间时，我们看着金属环不断旋转。</p><p><strong>易错：</strong> We saw the panel to move 在主动感官结构中多了 to；应写 move 或 moving，取决于观察视角。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-018">Lesson 18</a></p><h2 id="have-加宾语加过去分词" tabindex="-1">have 加宾语加过去分词 <a class="header-anchor" href="#have-加宾语加过去分词" aria-label="Permalink to &quot;have 加宾语加过去分词 {#have-加宾语加过去分词}&quot;">​</a></h2><p>have something done 常表示安排别人完成某事，如 have a lock replaced；也可表示遭遇不幸，如 have a bag stolen，不能理解为主动安排偷窃。判断依赖动词和上下文。have someone do something 则让某人执行动作，do 用原形；have someone doing 可强调持续状态。此结构中的时态体现在 have 上，done 随动词采用过去分词。表达动物护理时还要说明实际服务者或目的，避免把语法上的安排误写成已经发生的结果。</p><p><strong>L19 原创例句：</strong> After the gate broke, we had a new lock fitted to keep the dog safely inside.</p><p>大门坏后，我们请人安装了新锁，让狗安全地留在里面。</p><p><strong>易错：</strong> He had his wallet stolen 通常表示钱包被偷的遭遇，不能仅凭 had 就翻译为“他请人偷钱包”。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-019">Lesson 19</a></p><h2 id="过去将来时与计划结果" tabindex="-1">过去将来时与计划结果 <a class="header-anchor" href="#过去将来时与计划结果" aria-label="Permalink to &quot;过去将来时与计划结果 {#过去将来时与计划结果}&quot;">​</a></h2><p>would 加动词原形可表示从过去看未来，常见于间接引语；was 或 were going to 也表示当时的计划或明显趋势。was to do 可用于安排或后来注定发生的事件，语域较书面。过去将来时本身不能证明计划实际完成，因此需要另一句交代结果。would 也可表示过去习惯或条件句结果，必须结合时间背景判断。写历史人物时，先建立“当时”这个观察点，再描述他们预计会发生什么，读者才不会把预期与事实混淆。</p><p><strong>L20 原创例句：</strong> The pilot believed that the lighter engine would extend the aircraft&#39;s range.</p><p>飞行员相信较轻的发动机会扩大飞机的航程。</p><p><strong>易错：</strong> He was going to fly at dawn 不保证他确实起飞；如果天气取消计划，原句仍然可以成立。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-020">Lesson 20</a></p><h2 id="完成时不定式的先后关系" tabindex="-1">完成时不定式的先后关系 <a class="header-anchor" href="#完成时不定式的先后关系" aria-label="Permalink to &quot;完成时不定式的先后关系 {#完成时不定式的先后关系}&quot;">​</a></h2><p>to have 加过去分词表示不定式动作早于主句参照时间，常见于 seem、appear、be said 等结构。He seems to have left 表示现在看来他此前已经离开；He seemed to have left 则把观察点也放在过去。to do 通常表示同时状态或随后动作，不能一概理解为将来。be said to 仅说明有人这样说，不等于事实已获证实。写人物传记时，要用时间状语或来源说明限制推断，不能让复杂结构代替证据。</p><p><strong>L21 原创例句：</strong> The retired athlete appears to have inspired a new generation of coaches.</p><p>这位退役运动员似乎已经启发了新一代教练。</p><p><strong>易错：</strong> He seems to won 不成立；强调此前获胜应写 seems to have won，描述经常获胜则可用 seems to win。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-021">Lesson 21</a></p><h2 id="should-have-done-的过去评价" tabindex="-1">should have done 的过去评价 <a class="header-anchor" href="#should-have-done-的过去评价" aria-label="Permalink to &quot;should have done 的过去评价 {#should-have-done-的过去评价}&quot;">​</a></h2><p>should have 加过去分词常表示过去本该做而未做，带有遗憾或批评；shouldn&#39;t have done 常表示做了不该做的事。它也可在特定上下文表示对过去或现在完成情况的合理预期，如包裹按安排应已到达，因此不能见到结构就断言未发生。判断要看上下文是否明确出现失误。must have done 则通常是较强的过去推断，不等同于过去义务。评价他人准备工作时，应说明根据和后果，而非单独一句责备。</p><p><strong>L22 原创例句：</strong> I missed my cue because I had not rehearsed; I should have checked the recording twice.</p><p>我因为没有排练而错过提示；我本该检查两遍录音。</p><p><strong>易错：</strong> I should checked 错缺 have；过去评价用 should have checked，当前建议用 should check。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-022">Lesson 22</a></p><h2 id="prefer-与-would-rather" tabindex="-1">prefer 与 would rather <a class="header-anchor" href="#prefer-与-would-rather" aria-label="Permalink to &quot;prefer 与 would rather {#prefer-与-would-rather}&quot;">​</a></h2><p>prefer A to B 中 to 是介词，A 和 B 应保持结构平行，可以同为名词或动名词。prefer to do rather than do 中前半为不定式，rather than 后通常用原形。would rather 后接动词原形，否定为 would rather not do；如果后接另一个人的完整分句，常用过去式表示现在或将来的愿望。比较偏好必须明确选择对象，不要把个人喜好包装为客观优劣。prefer 通常已含比较意味，无须再加 more。</p><p><strong>L23 原创例句：</strong> I prefer tasting a small portion to rejecting an unfamiliar dish immediately.</p><p>我更愿意先尝一小份，而不是立刻拒绝陌生菜肴。</p><p><strong>易错：</strong> I prefer tea than coffee 应改为 prefer tea to coffee；would rather drink tea than coffee 是另一结构。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-023">Lesson 23</a></p><h2 id="同位语从句与定语从句" tabindex="-1">同位语从句与定语从句 <a class="header-anchor" href="#同位语从句与定语从句" aria-label="Permalink to &quot;同位语从句与定语从句 {#同位语从句与定语从句}&quot;">​</a></h2><p>fact、news、idea、belief 等名词后可接 that 从句说明名词的具体内容，这种 that 通常只起连接作用，不在从句中担任主语或宾语。定语从句则修饰或限定名词，其中关系词在从句里有成分作用。the news that shocked us 中 that 是主语；the news that the shop had closed 中从句已完整，that 引出新闻内容。不是每个抽象名词都自然接受同位语从句，要结合常用搭配；表达疑问内容时还可用 whether。</p><p><strong>L24 原创例句：</strong> The discovery that the letter was unsigned raised new questions.</p><p>发现那封信没有签名这件事引出了新的疑问。</p><p><strong>易错：</strong> The letter that was unsigned 中 that 作从句主语；the fact that the letter was unsigned 中 that 不作句子成分。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-024">Lesson 24</a></p><h2 id="过去完成进行时" tabindex="-1">过去完成进行时 <a class="header-anchor" href="#过去完成进行时" aria-label="Permalink to &quot;过去完成进行时 {#过去完成进行时}&quot;">​</a></h2><p>had been 加动词 ing 表示在过去某个时间点之前持续进行的动作，常与 for、since 连用，强调过程或留下的迹象。过去完成时更容易突出完成结果或数量，例如 had sailed 200 miles；过去完成进行时强调 had been sailing for two days。两种结构有时都可用，但观察焦点不同。know、own 等状态动词通常不采用进行体。持续时长并不自动说明动作在参照点后结束，应由上下文另行交代是否继续。</p><p><strong>L25 原创例句：</strong> The crew had been sailing for six hours when the wind finally changed.</p><p>风向终于改变时，船员们已经航行了六个小时。</p><p><strong>易错：</strong> had been sailed 是被动形式的一部分，不等于 had been sailing；主动进行需要 ing。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-025">Lesson 25</a></p><h2 id="too-与-enough-的位置" tabindex="-1">too 与 enough 的位置 <a class="header-anchor" href="#too-与-enough-的位置" aria-label="Permalink to &quot;too 与 enough 的位置 {#too-与-enough-的位置}&quot;">​</a></h2><p>too 加形容词再加 to do，通常表示程度过高以至于不能或不宜完成某动作。形容词加 enough 再加 to do 表示达到所需程度，而 enough 放在名词前，如 enough space。需要说明动作执行者时可在不定式前加 for someone。not large enough 与 too small 常在特定目的下近义，但不等于所有语境都能互换。too pleased to help 等固定语气还可能表达非常乐意，因此解释时应结合形容词意义和实际语境。</p><p><strong>L26 原创例句：</strong> The tin is wide enough to hold the cards, but it is too shallow for the wooden pieces.</p><p>这个盒子宽到足以装下卡片，但对于木制部件来说太浅。</p><p><strong>易错：</strong> enough wide 应为 wide enough；wide enough space 则应根据所指改写为 enough space 或 a sufficiently wide space。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-026">Lesson 26</a></p><h2 id="不定代词的后置修饰" tabindex="-1">不定代词的后置修饰 <a class="header-anchor" href="#不定代词的后置修饰" aria-label="Permalink to &quot;不定代词的后置修饰 {#不定代词的后置修饰}&quot;">​</a></h2><p>something、anything、nothing 等后面接形容词时，形容词通常后置，如 something useful。后接不定式可说明待做事项，如 nothing to buy。nothing 本身带否定意义，标准英语中通常不再加 not 构成同一否定；I don&#39;t need anything 与 I need nothing 意思接近，但后者可能更强调。not everything 表示并非全部，不等于 nothing。选择 some 或 any 不只看肯定否定，还要考虑请求、邀请和预期答案等语用条件。</p><p><strong>L27 原创例句：</strong> We found nothing expensive in the cabin, but there was everything we needed.</p><p>我们在小屋里没发现昂贵物品，但需要的东西一应俱全。</p><p><strong>易错：</strong> I don&#39;t need nothing 在标准书面英语里应改为 I don&#39;t need anything；not everything 不是“什么都不”。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-027">Lesson 27</a></p>',63)])])}const f=o(r,[["render",s]]);export{c as __pageData,f as default};
